import { describe, it, expect } from "vitest";
import { createChaseCamera } from "./chase-camera.js";
import { createBankedFreeCamera } from "@babylonjs/lite";

// Picture-up of camera: world-space direction of camera local +Y.
function pictureUp(c: any): number[] {
    const m = c.worldMatrix;
    return [m[4], m[5], m[6]];
}
const dot = (a: number[], b: number[]) => a[0]*b[0]+a[1]*b[1]+a[2]*b[2];
const norm = (a: number[]) => Math.hypot(a[0], a[1], a[2]);

describe("chase camera", () => {
    it("starts upright and looks at target", () => {
        const cc = createChaseCamera({ x: 0, y: 0, z: 0 }, { x: 0, y: 0, z: 10 });
        const up = pictureUp(cc.camera);
        expect(up[1]).toBeCloseTo(1);
        expect(Math.abs(up[0]) + Math.abs(up[2])).toBeLessThan(1e-9);
    });

    it("rolls to match a tilted up, perpendicular to view", () => {
        const cc = createChaseCamera({ x: 0, y: 0, z: 0 }, { x: 0, y: 0, z: 10 });
        const u = { x: Math.SQRT1_2, y: Math.SQRT1_2, z: 0 };
        cc.bank(u);
        const p = pictureUp(cc.camera);
        expect(dot(p, [u.x, u.y, u.z])).toBeCloseTo(1, 6);
        // still looking at target: local +Z = forward
        const m = cc.camera.worldMatrix;
        expect(m[8]).toBeCloseTo(0); expect(m[9]).toBeCloseTo(0); expect(m[10]).toBeCloseTo(1);
    });

    it("up with a view-direction component: picture up is projection", () => {
        const cc = createChaseCamera({ x: 0, y: 0, z: 0 }, { x: 0, y: 0, z: 10 });
        const u = { x: 0.6, y: 0.0, z: 0.8 }; // along forward partly
        cc.bank({ x: 0.6, y: 0.8, z: 0.0 });
        const p = pictureUp(cc.camera);
        expect(dot(p, [0, 1, 0])).toBeGreaterThan(0.79);
        expect(p[2]).toBeCloseTo(0, 6);
        void u;
    });

    it("degenerate up keeps previous roll, both directions", () => {
        const cc = createChaseCamera({ x: 0, y: 0, z: 0 }, { x: 0, y: 0, z: 10 });
        const u = { x: 1, y: 0, z: 0 };
        cc.bank(u);
        const before = pictureUp(cc.camera);
        cc.bank({ x: 0, y: 0, z: 1 });
        cc.bank({ x: 0, y: 0, z: -1 });
        const after = pictureUp(cc.camera);
        expect(after).toEqual(before);
        const m = cc.camera.worldMatrix;
        expect(m[10]).toBeCloseTo(1);
    });

    it("degenerate at start keeps upright-start, no NaN", () => {
        const cc = createChaseCamera({ x: 0, y: 0, z: 0 }, { x: 0, y: 0, z: 10 });
        cc.bank({ x: 0, y: 0, z: 1 });
        const m = cc.camera.worldMatrix;
        for (const v of m) expect(Number.isNaN(v)).toBe(false);
        expect(norm(pictureUp(cc.camera))).toBeCloseTo(1);
    });

    it("matches direct library banking", () => {
        const eye = { x: 1, y: 2, z: 3 }, tgt = { x: -2, y: 5, z: 7 };
        const cc = createChaseCamera(eye, tgt);
        const ref = createBankedFreeCamera(eye, tgt);
        const u = { x: 0.3, y: 0.9, z: -0.3 };
        const l = Math.hypot(u.x,u.y,u.z); const un = { x: u.x/l, y: u.y/l, z: u.z/l };
        cc.bank(un);
        ref.upVector.x = un.x; ref.upVector.y = un.y; ref.upVector.z = un.z;
        const a = cc.camera.worldMatrix, b = ref.worldMatrix;
        for (let i = 0; i < 16; i++) expect(a[i]).toBeCloseTo(b[i], 6);
    });
});
